pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(uint256 _val) public {
        vm.assume(_val > 0);
        c.SetMinSum(_val);
        c.Initialized();
        assertTrue(c.MinSum() == _val);
    }
}
